// Munkatársak listájának feldolgozása és munkaidő ellenőrzés
const employees = $input.all();
const today = new Date();
const weekStart = new Date(today);
weekStart.setDate(today.getDate() - (today.getDay() || 7) + 1); // Hétfő

const results = [];

for (const employee of employees) {
  const employeeData = employee.json;
  const telegramChatId = employeeData['Telegram Chat ID'] || employeeData['Telegram ChatId'] || null;
  const name = employeeData['Név'] || employeeData['Name'] || 'Ismeretlen';

  if (!telegramChatId) {
    continue; // Nincs Telegram chat ID, kihagyjuk
  }

  results.push({
    json: {
      chatId: telegramChatId,
      name: name,
      employeeId: employeeData.id
    }
  });
}

return results;

// Ellenőrzés: van-e munkaidő bejegyzés a héten
const employee = $('Munkatársak Feldolgozás').item.json;
const worktimeRecords = $input.all();

const today = new Date();
const weekStart = new Date(today);
weekStart.setDate(today.getDate() - (today.getDay() || 7) + 1);
weekStart.setHours(0, 0, 0, 0);

// Szűrés: csak az elmúlt 7 nap rekordjai
const thisWeekRecords = worktimeRecords.filter(record => {
  const recordDate = new Date(record.json.Dátum);
  return recordDate >= weekStart;
});

const hasRecords = thisWeekRecords.length > 0;
const recordCount = thisWeekRecords.length;

let message = `👋 **${employee.name}**,\n\n`;

if (hasRecords) {
  message += `✅ Köszönjük! A héten **${recordCount}** munkaidő bejegyzésed van rögzítve.\n\n`;
  message += '💡 Ha még van munkaidő, amit elfelejtettél, küldd el most!\n';
  message += 'Példa: "Ma 4 órát dolgoztam adminisztrációval"';
} else {
  message += '⚠️ **Figyelem!**\n\n';
  message += 'A héten még nincs rögzített munkaidő bejegyzésed.\n\n';
  message += '📝 Kérlek, rögzítsd a munkaidődet!\n\n';
  message += '💡 Példa üzenetek:\n';
  message += '• "Ma 8 órát dolgoztam"\n';
  message += '• "Kezdtem 9:00, befejeztem 17:00"\n';
  message += '• "Tegnap 6 órát dolgoztam"';
}

message += '\n\n📊 Használd a /statusz parancsot a mai státuszhoz, vagy /het a heti összesítőhöz.';

return [{
  json: {
    chatId: employee.chatId,
    name: employee.name,
    message: message,
    hasRecords: hasRecords,
    recordCount: recordCount
  }
}];

